def dimension_noise(server_dir, level, pack, overworld):
    """The noise settings of the dimension of the data (# noise_settings):
    the overworld's (already checked) for the overworld, else the pack's own
    dimension file or what the saved world stores for the dimension."""
    if DIMENSION is None:
        return overworld
    if pack:
        s = pack.dimension_settings(DIMENSION)
        if s is not None:
            return s
    s = mcworld.dimension_noise_settings(os.path.join(server_dir, level), DIMENSION)
    return s if isinstance(s, str) else "inline"


def in_dim(cmd):
    """A command run in the dimension of the data (--dimension)."""
    if DIMENSION is None:
        return cmd
    if cmd.startswith("execute "):
        return "execute in %s %s" % (DIMENSION, cmd[len("execute "):])
    return "execute in %s run %s" % (DIMENSION, cmd)


def dim_region_dir(server_dir, level):
    if DIMENSION is None:
        return pr.region_dir(server_dir, level)
    ns, path = DIMENSION.split(":", 1)
    cands = [os.path.join(server_dir, level, "dimensions", ns, *path.split("/"), "region")]
    # the vanilla Nether and End before 26.1
    cands += [os.path.join(server_dir, level, d[1], "region") for d in DIMENSIONS.values() if d[0] == DIMENSION]
    for p in cands:
        if os.path.isdir(p):
            return p
    raise RuntimeError("no region dir of %s in %s" % (DIMENSION, level))


def probe_y():
    """A block height inside the dimension for the 'is it loaded' tests."""
    return 0 if MIN_Y <= 0 < MIN_Y + HEIGHT else MIN_Y


def biome_levels(min_y, height):
    """The y of the B lines: the levels of the existing files where the
    dimension has their range, else ten levels from the bottom to the top."""
    if (min_y, height) == (-64, 384):
        return OVERWORLD_BIOME_Y
    if (min_y, height) == (0, 256):
        return DIMENSIONS["nether"][5]
    lo, hi = min_y + 4, min_y + height - 4
    return tuple(sorted({lo + (hi - lo) * i // 9 // 4 * 4 for i in range(10)}))

