def log(*a):
    print(time.strftime("%H:%M:%S"), *a, flush=True)


def version_tuple(mc):
    return [int(v) for v in re.findall(r"\d+", mc)]


def can_freeze(mc):
    """'/tick freeze' exists since 1.20.3."""
    return version_tuple(mc) >= [1, 20, 3]


def has_if_biome(mc):
    """'execute if biome' exists since 1.19.3."""
    return version_tuple(mc) >= [1, 19, 3]


# ------------------------------------------------------------------ datapack

def pack_files(folder):
    """Relative paths ('/' separated, sorted) of the files of a pack folder.

    Hidden files and directories, __pycache__ and anything outside of
    pack.mcmeta, pack.png and the directories next to them are left out.
    """
    out = []
    for root, dirs, files in os.walk(folder):
        dirs[:] = sorted(d for d in dirs if not d.startswith(".") and d != "__pycache__")
        for name in files:
            rel = os.path.relpath(os.path.join(root, name), folder).replace(os.sep, "/")
            if name.startswith("."):
                continue
            if "/" not in rel and name not in ("pack.mcmeta", "pack.png"):
                continue  # scripts or notes next to pack.mcmeta are not part of the pack
            out.append(rel)
    return sorted(out)


def zip_pack(folder, dst):
    """Write a pack folder as a reproducible zip: sorted names, fixed date, stored."""
    names = pack_files(folder)
    if "pack.mcmeta" not in names:
        raise SystemExit("%s is not a data pack (no pack.mcmeta)" % folder)
    with zipfile.ZipFile(dst, "w", zipfile.ZIP_STORED) as z:
        for rel in names:
            info = zipfile.ZipInfo(rel, date_time=(1980, 1, 1, 0, 0, 0))
            info.external_attr = 0o644 << 16
            with open(os.path.join(folder, *rel.split("/")), "rb") as f:
                z.writestr(info, f.read())
    return len(names)


class Pack:
    """A data pack to be placed into every new world: name, zip file, sha1, overworld settings."""

    def __init__(self, path, work, name=None):
        path = os.path.abspath(path)
        self.name = name or re.sub(r"\.zip$", "", os.path.basename(path.rstrip(os.sep)))
        if not re.match(r"^[a-z0-9_.-]+$", self.name):
            raise SystemExit("pack name %r: use lower case letters, digits, _ . -" % self.name)
        if os.path.isdir(path):
            self.zip = os.path.join(work, "datapack-%s.zip" % self.name)
            self.files = zip_pack(path, self.zip)
        else:
            self.zip = path
            with zipfile.ZipFile(path) as z:
                self.files = sum(1 for n in z.namelist() if not n.endswith("/"))
        self.sha1 = pr.sha1_of(self.zip)
        # What the pack says about the overworld (None: it does not replace the dimension).
        self.settings, self.entries = None, None
        with zipfile.ZipFile(self.zip) as z:
            if "data/minecraft/dimension/overworld.json" in z.namelist():
                gen = json.loads(z.read("data/minecraft/dimension/overworld.json"))["generator"]
                s = gen.get("settings")
                self.settings = s if isinstance(s, str) else "inline"
                biomes = gen.get("biome_source", {}).get("biomes")
                self.entries = len(biomes) if isinstance(biomes, list) else None

    def dimension_settings(self, dimension):
        """The noise settings the pack's own file of @dimension names ('inline'
        for inline settings), or None if the pack does not replace it."""
        ns, path = dimension.split(":", 1)
        name = "data/%s/dimension/%s.json" % (ns, path)
        with zipfile.ZipFile(self.zip) as z:
            if name not in z.namelist():
                return None
            s = json.loads(z.read(name))["generator"].get("settings")
        return s if isinstance(s, str) else "inline"

    def use_format(self, fmt):
        """Selects the overlays of pack.mcmeta that apply to the data pack
        format @fmt ((major, minor), see data_format()): later overlays win
        over earlier ones and over the pack itself, as in the game. Overlays
        exist since format 18; before format 82 an entry is read from its
        "formats" alone, and one entry without it drops all overlays."""
        self.layers = [""]
        with zipfile.ZipFile(self.zip) as z:
            try:
                meta = json.loads(z.read("pack.mcmeta").decode("utf-8-sig"))
            except (KeyError, ValueError):
                return
        if fmt[0] < 18:
            return
        applies = []
        for e in (meta.get("overlays") or {}).get("entries") or []:
            if fmt[0] < 82:
                f = e.get("formats")
                rng = format_range({"formats": f}, "formats")
                if not e.get("directory") or not rng or (isinstance(f, list) and len(f) != 2) or rng[0] > rng[1]:
                    return
            else:
                rng = format_range(e, "formats")
            if e.get("directory") and rng and rng[0] <= fmt <= rng[1]:
                applies.append(e["directory"].rstrip("/") + "/")
        self.layers += applies

    def json(self, rel):
        """A file of the pack (path below data/) with the overlays applied, or None."""
        with zipfile.ZipFile(self.zip) as z:
            names = set(z.namelist())
            for layer in reversed(getattr(self, "layers", [""])):
                if layer + "data/" + rel in names:
                    return json.loads(z.read(layer + "data/" + rel).decode("utf-8-sig"))
        return None

    def resource(self, registry, ref):
        """The pack's file of a registry entry named by @ref ("ns:path"), or None."""
        ns, path = ref.split(":", 1) if ":" in ref else ("minecraft", ref)
        return self.json("%s/%s/%s.json" % (ns, registry, path))


    def install(self, server_dir, level):
        """Copy the zip into <world>/datapacks; the world itself must not exist yet."""
        d = os.path.join(server_dir, level, "datapacks")
        os.makedirs(d)
        shutil.copyfile(self.zip, os.path.join(d, self.name + ".zip"))
        if TERRAIN_ONLY:
            # its name sorts after the pack's, so it is enabled after it and wins
            shutil.copyfile(TERRAIN_ONLY, os.path.join(d, TERRAIN_ONLY_NAME + ".zip"))

    def check_world(self, server_dir, level):
        """The saved world must have the pack enabled and use its overworld generator.

        Returns the id of the overworld noise settings stored in the world
        ('inline' if the world stores the settings themselves).
        """
        wdir = os.path.join(server_dir, level)
        dat = mcworld.read_nbt_file(os.path.join(wdir, "level.dat"))["Data"]
        enabled = list(dat.get("DataPacks", {}).get("Enabled", []))
        if "file/%s.zip" % self.name not in enabled:
            raise SystemExit("world %s: pack %s is not enabled (enabled: %s)" % (level, self.name, enabled))
        if TERRAIN_ONLY:
            last = "file/%s.zip" % TERRAIN_ONLY_NAME
            if last not in enabled or enabled.index(last) < enabled.index("file/%s.zip" % self.name):
                raise SystemExit("world %s: the terrain-only pack is not enabled after the pack (enabled: %s)"
                                 % (level, enabled))
        if os.path.exists(os.path.join(wdir, "data", "minecraft", "world_gen_settings.dat")):
            # 26.1+ stores the dimensions of the world preset there; a data
            # pack's dimension replaces them only when the world is loaded, so
            # the file tells nothing about the pack. The biomes of the written
            # file show whether the pack generated the world.
            return self.settings
        got = mcworld.overworld_noise_settings(wdir)
        got = got if isinstance(got, str) else "inline"
        if self.settings is not None and got != self.settings:
            raise SystemExit("world %s: overworld noise settings are %r, the pack says %r"
                             % (level, got, self.settings))
        if self.entries is not None:
            # 26.1+ keeps the generator in its own file, older versions in level.dat
            path = os.path.join(wdir, "data", "minecraft", "world_gen_settings.dat")
            wgs = mcworld.read_nbt_file(path)["data"] if os.path.exists(path) else dat["WorldGenSettings"]
            src = wgs["dimensions"]["minecraft:overworld"]["generator"]["biome_source"]
            n = len(src.get("biomes", []))
            if n != self.entries:
                raise SystemExit("world %s: biome source has %d entries, the pack has %d"
                                 % (level, n, self.entries))
        return got


FORMAT_TOP = 1 << 31


def format_range(o, range_key):
    """The (lo, hi) format range of a pack section or overlay entry, as
    (major, minor) tuples, or None: like the game, from "min_format" /
    "max_format" (a number or [major, minor]) over the older range key."""
    def num(v):
        # the game's integer codec takes the integer part of a number
        return int(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None

    def rng(v):
        if num(v) is not None:
            return num(v), num(v)
        if isinstance(v, list) and v and num(v[0]) is not None and num(v[-1]) is not None:
            return num(v[0]), num(v[-1])
        if isinstance(v, dict) and num(v.get("min_inclusive")) is not None \
                and num(v.get("max_inclusive")) is not None:
            return num(v["min_inclusive"]), num(v["max_inclusive"])
        return None

    def ver(v, top):
        if num(v) is not None:
            return (num(v), FORMAT_TOP if top else 0)
        if isinstance(v, list) and v and all(num(x) is not None for x in v[:2]):
            return (num(v[0]), num(v[1]) if len(v) > 1 else (FORMAT_TOP if top else 0))
        return None
    lo = hi = None
    r = rng(o.get(range_key))
    if r:
        lo, hi = (r[0], 0), (r[1], 0)
    v = ver(o.get("min_format"), False)
    if v:
        lo, hi = v, hi or (FORMAT_TOP, FORMAT_TOP)
    v = ver(o.get("max_format"), True)
    if v:
        lo, hi = lo or (0, 0), v
    return (lo, hi) if lo else None


def data_format(jar):
    """The data pack format of a server jar as (major, minor), from its version.json."""
    with zipfile.ZipFile(jar) as z:
        pv = json.loads(z.read("version.json"))["pack_version"]
    if isinstance(pv, int):
        return (pv, 0)
    if "data" in pv:
        return (pv["data"], 0)
    return (pv["data_major"], pv.get("data_minor", 0))


def dimension_geometry(dim, pack):
    """(min_y, height, logical_height, has_ceiling, sea_level) of a dimension:
    the type and noise settings its generator names, from the pack's files
    where it has them, else the game's."""
    type_ref, settings = PRESET_DIMENSIONS.get(dim, (None, None))
    if pack:
        ns, path = dim.split(":", 1)
        d = pack.json("%s/dimension/%s.json" % (ns, path))
        if d is not None:
            type_ref = d.get("type")
            settings = d.get("generator", {}).get("settings")
    if type_ref is None:
        raise SystemExit("dimension %s: neither the world presets nor the pack define it" % dim)
    t = type_ref if isinstance(type_ref, dict) else (pack.resource("dimension_type", type_ref) if pack else None)
    if t is None:
        if type_ref not in VANILLA_TYPES:
            raise SystemExit("dimension %s: unknown dimension type %s" % (dim, type_ref))
        geo = VANILLA_TYPES[type_ref]
    else:
        geo = (t["min_y"], t["height"], t.get("logical_height", t["height"]), bool(t.get("has_ceiling")))
    s = settings if isinstance(settings, dict) else \
        (pack.resource("worldgen/noise_settings", settings) if pack and isinstance(settings, str) else None)
    if s is not None:
        sea = s.get("sea_level", 0)
    elif isinstance(settings, str) and settings in VANILLA_SEA_LEVEL:
        sea = VANILLA_SEA_LEVEL[settings]
    else:
        sea = 0     # no noise generator (flat, debug): nothing below it is water
    return geo + (sea,)


# --terrain-only: a second pack, made at run time from the biomes and
# structure sets of the pack and of the game, that keeps the terrain and the
# biomes but places nothing else: every biome without features and carvers,
# every structure set with frequency 0. The H lines are then the terrain of
# the noise settings (and their surface rule) alone, which a generator of
# the terrain can match block for block.
TERRAIN_ONLY = None
TERRAIN_ONLY_NAME = "zzz-terrain-only"
ZOOM = 0        # --zoom: number of Z positions (the 1:1 biome of single blocks)


def game_data(jar):
    """The ZipFile that holds the game's data (the jar nested in the bundler of 1.18+)."""
    outer = zipfile.ZipFile(jar)
    if "META-INF/versions.list" not in outer.namelist():
        return outer
    line = outer.read("META-INF/versions.list").decode().strip().splitlines()[0]
    data = outer.read("META-INF/versions/" + line.split("\t")[2])
    outer.close()
    return zipfile.ZipFile(io.BytesIO(data))


def make_terrain_only(pack, jar, fmt, dst):
    """Writes the terrain-only pack for @pack (or the game alone) to @dst."""
    files = {}
    with game_data(jar) as z:
        for n in z.namelist():
            if re.match(r"^data/minecraft/worldgen/(biome|structure_set)/[a-z0-9_./-]+\.json$", n):
                files[n[len("data/"):]] = json.loads(z.read(n).decode("utf-8-sig"))
    if pack:
        with zipfile.ZipFile(pack.zip) as z:
            names = z.namelist()
        for n in names:
            for layer in pack.layers:
                m = re.match(r"^%sdata/([a-z0-9_.-]+/worldgen/(?:biome|structure_set)/[a-z0-9_./-]+\.json)$"
                             % re.escape(layer), n)
                if m and pack.json(m.group(1)) is not None:
                    files[m.group(1)] = pack.json(m.group(1))
    biomes = sets = 0
    with zipfile.ZipFile(dst, "w", zipfile.ZIP_DEFLATED) as out:
        if fmt[0] >= 82:
            meta = {"pack": {"description": "terrain only", "min_format": fmt[0], "max_format": fmt[0]}}
        else:
            meta = {"pack": {"description": "terrain only", "pack_format": fmt[0]}}
        out.writestr("pack.mcmeta", json.dumps(meta))
        for rel, j in sorted(files.items()):
            if not isinstance(j, dict):
                continue
            if "/worldgen/biome/" in rel:
                j["features"] = []
                if isinstance(j.get("carvers"), dict):
                    j["carvers"] = {}
                elif "carvers" in j:
                    j["carvers"] = []
                biomes += 1
            else:
                if not isinstance(j.get("placement"), dict):
                    continue
                j["placement"]["frequency"] = 0.0
                sets += 1
            out.writestr("data/" + rel, json.dumps(j))
    return biomes, sets


def startup_problems(log_path, offset):
    """WARN and ERROR lines the server logged since offset (the JVM's own warnings are not log lines)."""
    with open(log_path, errors="replace") as f:
        f.seek(offset)
        return [ln.rstrip("\n") for ln in f
                if re.match(r"^\[[0-9:]+\] \[[^\]]+/(WARN|ERROR)\]", ln) and "Can't keep up" not in ln
            # the operating system's version, not the pack (newer macOS)
            and "to a codename" not in ln]


# ---------------------------------------------------------------- worlds file

class Area:
    def __init__(self, name, cx0, cz0, nx, nz):
        self.name, self.cx0, self.cz0, self.nx, self.nz = name, cx0, cz0, nx, nz

    def chunks(self):
        return [(cx, cz) for cx in range(self.cx0, self.cx0 + self.nx)
                for cz in range(self.cz0, self.cz0 + self.nz)]

    def box(self):
        """Block coordinates, both corners inclusive."""
        return (self.cx0 * 16, self.cz0 * 16,
                (self.cx0 + self.nx) * 16 - 1, (self.cz0 + self.nz) * 16 - 1)

    def blocks_of_chunks(self):
        """Split into force-load requests of at most BLOCK x BLOCK chunks: (cx0, cz0, cx1, cz1)."""
        out = []
        for bx in range(self.cx0, self.cx0 + self.nx, BLOCK):
            for bz in range(self.cz0, self.cz0 + self.nz, BLOCK):
                out.append((bx, bz, min(bx + BLOCK, self.cx0 + self.nx) - 1,
                            min(bz + BLOCK, self.cz0 + self.nz) - 1))
        return out


def parse_worlds(path):
    """Lines: '<seed> <name>:<chunk_x0>,<chunk_z0>,<chunks_x>,<chunks_z> ...'."""
    out = []
    with open(path) as f:
        for line in f:
            line = line.split("#", 1)[0].strip()
            if not line:
                continue
            p = line.split()
            areas = []
            for spec in p[1:]:
                name, nums = spec.split(":")
                areas.append(Area(name, *[int(v) for v in nums.split(",")]))
            seen = set()
            for a in areas:
                cs = set(a.chunks())
                if cs & seen:
                    raise SystemExit("seed %s: area %s overlaps another area" % (p[0], a.name))
                seen |= cs
            out.append((int(p[0]), areas))
    return out


# -------------------------------------------------------------------- server

def probe_loaded(srv, chunks, timeout=1800):
    """Wait until vanilla reports a block of every chunk as loaded."""
    end = time.time() + timeout
    pending = list(chunks)
    while pending:
        if time.time() > end:
            raise TimeoutError("chunks not loaded: %s" % pending[:5])
        # A block test fails with "not loaded" until the chunk is loaded as a full
        # chunk; it never triggers loading itself. One reply per command, in order.
        for cx, cz in pending:
            srv.send(in_dim("execute unless block %d %d %d minecraft:structure_void" % (cx * 16, probe_y(), cz * 16)))
        still = []
        for cx, cz in pending:
            if srv.wait_for(LOADED_RE, 300).group(1) != "passed":
                still.append((cx, cz))
        pending = still
        if pending:
            time.sleep(1)


def has_if_loaded(mc):
    """'execute if loaded' exists since 1.19.4."""
    return version_tuple(mc) >= [1, 19, 4]


def probe_ticking(srv, chunks, timeout=600):
    """Wait until every chunk is fully loaded in vanilla's sense (entity ticking).

    A chunk only runs its post-processing (e.g. mushrooms that cannot stay in
    daylight are removed) when it reaches that level, which is later than
    'loaded' for a block test. Releasing a chunk before that leaves the
    post-processing to whenever the chunk is loaded next.
    """
    end = time.time() + timeout
    pending = list(chunks)
    while pending:
        if time.time() > end:
            raise TimeoutError("chunks not ticking: %s" % pending[:5])
        for cx, cz in pending:
            srv.send(in_dim("execute if loaded %d %d %d" % (cx * 16, probe_y(), cz * 16)))
        pending = [c for c in pending if srv.wait_for(PASS_RE, 300).group(1) != "passed"]
        if pending:
            time.sleep(0.5)


def test(srv, cmd):
    """Run an 'execute if ...' command, True if vanilla reports 'Test passed'."""
    return srv.command(cmd, PASS_RE, 120).group(1) == "passed"


def generate(srv, areas, until_ticking=False):
    for a in areas:
        t0 = time.time()
        for (x0, z0, x1, z1) in a.blocks_of_chunks():
            box = "%d %d %d %d" % (x0 * 16, z0 * 16, x1 * 16, z1 * 16)
            m = srv.command(in_dim("forceload add " + box), FORCE_RE, 300)
            if m.group(1) == "Too many chunks":
                raise SystemExit("forceload refused: too many chunks in %s" % box)
            block = [(cx, cz) for cx in range(x0, x1 + 1) for cz in range(z0, z1 + 1)]
            probe_loaded(srv, block)
            if until_ticking:
                probe_ticking(srv, block)
            # release the block again so that the loaded set (and the heap) stays small
            srv.command(in_dim("forceload remove " + box), UNFORCE_RE, 300)
        log("  area %s: %d chunks generated in %.0f s" % (a.name, len(a.chunks()), time.time() - t0))


def read_chunks(world, areas):
    """All area chunks from disk; None if one is missing or not yet a full chunk."""
    out = {}
    for a in areas:
        for cx, cz in a.chunks():
            ch = world.chunk(cx, cz)
            if mcworld.chunk_status(ch) not in ("minecraft:full", "full"):  # 1.18.2: no namespace
                return None, (cx, cz, mcworld.chunk_status(ch))
            if (ch["xPos"], ch["zPos"]) != (cx, cz) or ch["yPos"] * 16 != MIN_Y:
                raise RuntimeError("chunk %d,%d: unexpected position/min_y" % (cx, cz))
            out[(cx, cz)] = ch
    return out, None


def extract(chunks, areas, any_namespace=False):
    """Returns (records per area, offline check statistics).

    any_namespace: biomes of other namespaces than 'minecraft' are expected
    (data pack worlds) and written with their namespace.

    records: area name -> (list of (x, z, ws, of), list of (x, y, z, biome)).
    Offline checks, on every H column: WORLD_SURFACE must equal the highest
    non-air block found by decoding the block states (a code path independent
    of the heightmap decoder), the block at OCEAN_FLOOR must not be a known
    non-blocking block and no known solid block may sit above OCEAN_FLOOR.
    """
    recs = {}
    st = {"h": 0, "b": 0, "ws_mismatch": 0, "of_on_nonblocking": 0, "solid_above_of": 0,
          "between": {}, "top_ws": {}, "top_of": {}}
    tops = {}
    for a in areas:
        hs, bs, fs = [], [], []
        for cx, cz in a.chunks():
            ch = chunks[(cx, cz)]
            ws = mcworld.heightmap(ch, "WORLD_SURFACE", HEIGHT)
            of = mcworld.heightmap(ch, "OCEAN_FLOOR", HEIGHT)
            view = mcworld.ChunkView(ch)
            for dx in range(0, 16, H_STEP):
                for dz in range(0, 16, H_STEP):
                    x, z = cx * 16 + dx, cz * 16 + dz
                    w, o = ws[dz * 16 + dx], of[dz * 16 + dx]
                    hs.append((x, z, w, o))
                    ty, tname = view.top_block(x, z)
                    if ty != w:
                        st["ws_mismatch"] += 1
                    oname = view.block(x, o, z) if o >= MIN_Y else None
                    if oname in NON_BLOCKING:
                        st["of_on_nonblocking"] += 1
                    for y in range(o + 1, w + 1):
                        n = view.block(x, y, z)
                        st["between"][n] = st["between"].get(n, 0) + 1
                        if SOLID.match(n):
                            st["solid_above_of"] += 1
                    st["top_ws"][tname or "-"] = st["top_ws"].get(tname or "-", 0) + 1
                    st["top_of"][oname or "-"] = st["top_of"].get(oname or "-", 0) + 1
                    if FLOOR_BELOW is not None:
                        fy = FLOOR_BELOW
                        while fy >= MIN_Y and view.block(x, fy, z) in NON_BLOCKING:
                            fy -= 1
                        fs.append((x, z, fy))
                    tops[(x, z)] = (tname, oname)
            for dx in range(0, 16, B_STEP):
                for dz in range(0, 16, B_STEP):
                    x, z = cx * 16 + dx, cz * 16 + dz
                    for y in BIOME_Y:
                        b = view.biome(x, y, z)
                        if b.startswith("minecraft:"):
                            b = b[len("minecraft:"):]
                        elif not any_namespace:
                            raise RuntimeError("unexpected biome id %r" % b)
                        bs.append((x, y, z, b))
        hs.sort(key=lambda r: (r[0], r[1]))
        bs.sort(key=lambda r: (r[0], r[2], r[1]))
        fs.sort(key=lambda r: (r[0], r[1]))
        FLOORS[a.name] = fs
        recs[a.name] = (hs, bs)
        st["h"] += len(hs)
        st["b"] += len(bs)
    return recs, st, tops


M64 = (1 << 64) - 1


def _lcg(s, salt):
    return ((s * (s * 6364136223846793005 + 1442695040888963407)) + salt) & M64


def _fiddle(s):
    return (((s >> 24) & 1023) / 1024.0 - 0.5) * 0.9


def zoomed_cell(seed, x, y, z):
    """The biome cell vanilla's BiomeManager.getBiome() reads for a block position.

    'execute if biome' does not read the cell that contains the block: the
    BiomeManager picks one of the 8 surrounding cells by a seeded, jittered
    nearest-cell search. This reproduces that choice so that the stored cells
    can be compared with what the command reports.
    """
    zs = struct.unpack("<Q", hashlib.sha256(struct.pack("<q", seed)).digest()[:8])[0]
    i, j, k = x - 2, y - 2, z - 2
    best, cell = None, None
    for p in range(8):
        ox, oy, oz = (p >> 2) & 1, (p >> 1) & 1, p & 1
        q, r, t = (i >> 2) + ox, (j >> 2) + oy, (k >> 2) + oz
        s = zs
        for salt in (q, r, t, q, r, t):
            s = _lcg(s, salt)
        fx = _fiddle(s)
        s = _lcg(s, zs)
        fy = _fiddle(s)
        s = _lcg(s, zs)
        fz = _fiddle(s)
        d = ((k & 3) / 4.0 - oz + fz) ** 2 + ((j & 3) / 4.0 - oy + fy) ** 2 + ((i & 3) / 4.0 - ox + fx) ** 2
        if best is None or d < best:
            best, cell = d, (q, r, t)
    # the chunk clamps the cell's y to the build height
    return cell[0], max(MIN_Y >> 2, min((MIN_Y + HEIGHT - 1) >> 2, cell[1])), cell[2]


def biome_tests(seed, chunks, bs, rnd, n):
    """Pick n block positions near B cells: (x, y, z, expected biome, mixed).

    Each position lies so that all 8 candidate cells are in the B cell's own
    chunk. 'mixed' tells whether those 8 cells hold more than one biome; such
    positions are preferred, because a uniform neighbourhood proves little.
    """
    cand = []
    for x, y, z, _ in rnd.sample(bs, min(len(bs), 40 * n)):
        view = mcworld.ChunkView(chunks[(x >> 4, z >> 4)])
        px, pz = x + 2 + rnd.randrange(4), z + 2 + rnd.randrange(4)
        py = min(MIN_Y + HEIGHT - 1, y + 2 + rnd.randrange(4))
        qx, qy, qz = zoomed_cell(seed, px, py, pz)
        around = {view.biome(x + dx, max(MIN_Y, min(MIN_Y + HEIGHT - 4, y + dy)), z + dz)
                  for dx in (0, 4) for dy in (0, 4) for dz in (0, 4)}
        cand.append((px, py, pz, view.biome(qx * 4, qy * 4, qz * 4), len(around) > 1))
    mixed = [c for c in cand if c[4]][:n - n // 4]
    return mixed + [c for c in cand if not c[4]][:n - len(mixed)]


def live_checks(srv, mc, seed, recs, tops, chunks, n=24):
    """Spot-check extracted values with vanilla's own block / biome predicates.

    Columns: the highest, some ocean columns, some where both heightmaps differ,
    some with negative coordinates, the rest random. Biomes (1.19.3+): block
    positions near B cells, see biome_tests(). Returns the counts checked.
    """
    rnd = random.Random(seed)
    # columns without any block (the void of the End) have nothing to test
    hs = [r for h, _ in recs.values() for r in h if r[2] >= MIN_Y]
    bs = [r for _, b in recs.values() for r in b]
    pick = sorted(hs, key=lambda r: -r[2])[:4]
    for cond in (lambda r: r[2] == SEA_LEVEL - 1 and r[3] < 50, lambda r: r[2] != r[3],
                 lambda r: r[0] < 0 and r[1] < 0, lambda r: True):
        cand = [r for r in hs if cond(r)]
        pick += rnd.sample(cand, min(len(cand), n // 4))
    bpick = biome_tests(seed, chunks, bs, rnd, n) if has_if_biome(mc) else []
    need = sorted({(r[0] >> 4, r[1] >> 4) for r in pick} | {(r[0] >> 4, r[2] >> 4) for r in bpick})
    for cx, cz in need:
        srv.send(in_dim("forceload add %d %d" % (cx * 16, cz * 16)))
    probe_loaded(srv, need)
    bad = []
    for x, z, w, o in pick:
        tname, oname = tops[(x, z)]
        if not test(srv, in_dim("execute if block %d %d %d %s" % (x, w, z, tname))):
            bad.append("block at WORLD_SURFACE %d %d %d is not %s" % (x, w, z, tname))
        if w < MIN_Y + HEIGHT - 1 and not any(test(srv, in_dim("execute if block %d %d %d %s" % (x, w + 1, z, air)))
                               for air in mcworld.AIR):
            bad.append("block above WORLD_SURFACE %d %d %d is not air" % (x, w + 1, z))
        if oname and not test(srv, in_dim("execute if block %d %d %d %s" % (x, o, z, oname))):
            bad.append("block at OCEAN_FLOOR %d %d %d is not %s" % (x, o, z, oname))
    for x, y, z, b, mixed in bpick:
        if not test(srv, in_dim("execute if biome %d %d %d %s" % (x, y, z, b))):
            bad.append("biome at %d %d %d is not %s (%s)" % (x, y, z, b, "mixed" if mixed else "uniform"))
    for cx, cz in need:
        srv.send(in_dim("forceload remove %d %d" % (cx * 16, cz * 16)))
    if bad:
        raise RuntimeError("in-game check disagrees: " + "; ".join(bad[:5]))
    return len(pick), len(bpick), sum(1 for c in bpick if c[4])


# Share of H columns that may change between the first save and the final state
# of a world that cannot be frozen (measured: about 0.1 %, flowing water and
# falling gravel). More than this means something else is going on.
MAX_DRIFT = 0.01


def far_from(areas):
    """A block position whose spawn chunks (radius 11) are far from every area."""
    return max(a.box()[2] for a in areas) + 160000, 64, 0


def offline_errors(st):
    return {k: st[k] for k in ("ws_mismatch", "of_on_nonblocking", "solid_above_of") if st[k]}


class Started(Server):
    """A Server whose failed start with a data pack ends the run: retrying cannot help."""

    def __init__(self, *a, pack=None, **kw):
        super().__init__(*a, **kw)
        self.pack = pack
        self.offset = 0
        self.problems = []

    def __enter__(self):
        if not self.pack:
            return super().__enter__()
        self.logf.flush()
        self.offset = os.path.getsize(self.logf.name)
        try:
            super().__enter__()
        except RuntimeError as e:
            for ln in startup_problems(self.logf.name, self.offset)[:20]:
                log("  " + ln[:300])
            raise SystemExit("the server did not start with pack %s (%s), see %s"
                             % (self.pack.name, e, self.logf.name))
        self.problems = startup_problems(self.logf.name, self.offset)
        return self


ALLOW_WARNINGS = False   # --allow-warnings


def check_startup(srv, logf):
    """A data pack the server logged warnings or errors for while loading
    (e.g. a registry entry it could not parse) is not what was meant: the run
    ends, unless --allow-warnings, which only counts them (the lines stay in
    the server log)."""
    if not srv.problems:
        return
    if ALLOW_WARNINGS:
        log("  the server logged %d warnings/errors while loading the pack (--allow-warnings), see %s"
            % (len(srv.problems), logf.name))
        return
    for ln in srv.problems[:20]:
        log("  " + ln[:300])
    raise SystemExit("the server logged %d warnings/errors while loading pack %s, see %s"
                     % (len(srv.problems), srv.pack.name, logf.name))


def zoom_positions(seed, chunks, rnd, n):
    """n block positions for Z lines: whose 8 candidate cells (all in saved
    chunks) hold more than one biome, so that the 1:1 zoom decides; a third
    of them in the lowest 8 blocks of the dimension, a third in the highest
    8 (where the game clamps the cells to the dimension). Returns
    (x, y, z, candidate biomes with the one of zoomed_cell() first)."""
    keys = sorted(chunks)
    views = {}

    def cell(qx, qy, qz):
        qy = max(MIN_Y >> 2, min((MIN_Y + HEIGHT - 1) >> 2, qy))
        c = (qx >> 2, qz >> 2)
        if c not in chunks:
            return None
        if c not in views:
            views[c] = mcworld.ChunkView(chunks[c])
        return views[c].biome(qx * 4, qy * 4, qz * 4)

    out, seen = [], set()
    for _ in range(400 * n):
        if len(out) >= n:
            break
        cx, cz = keys[rnd.randrange(len(keys))]
        x, z = cx * 16 + rnd.randrange(16), cz * 16 + rnd.randrange(16)
        band = len(out) % 3
        y = (MIN_Y + rnd.randrange(8) if band == 0 else MIN_Y + HEIGHT - 1 - rnd.randrange(8) if band == 1
             else MIN_Y + rnd.randrange(HEIGHT))
        if (x, y, z) in seen:
            continue
        seen.add((x, y, z))
        px, py, pz = (x - 2) >> 2, (y - 2) >> 2, (z - 2) >> 2
        around = [cell(px + dx, py + dy, pz + dz) for dx in (0, 1) for dy in (0, 1) for dz in (0, 1)]
        if None in around or len(set(around)) < 2:
            continue
        qx, qy, qz = zoomed_cell(seed, x, y, z)
        first = cell(qx, qy, qz)
        out.append((x, y, z, [first] + sorted(set(around) - {first})))
    return out


def zoom_reference(srv, seed, chunks, n):
    """Z lines: the biome vanilla reports for single blocks ('execute if
    biome', the game's 1:1 zoom of the stored cells). The chunks of the
    positions and their neighbours are loaded (the zoom reads neighbouring
    cells), the candidates are asked one after the other until one passes."""
    rnd = random.Random(seed ^ 0x5a5a)
    pos = zoom_positions(seed, chunks, rnd, n)
    by_chunk = {}
    for p in pos:
        by_chunk.setdefault((p[0] >> 4, p[2] >> 4), []).append(p)
    out = []
    groups = sorted(by_chunk)
    for g in range(0, len(groups), 8):
        part = groups[g:g + 8]
        need = sorted({(cx + dx, cz + dz) for cx, cz in part for dx in (-1, 0, 1) for dz in (-1, 0, 1)
                       if (cx + dx, cz + dz) in chunks})
        for cx, cz in need:
            srv.send(in_dim("forceload add %d %d" % (cx * 16, cz * 16)))
        probe_loaded(srv, need)
        todo = [(p, 0) for c in part for p in by_chunk[c]]
        while todo:
            for (x, y, z, cands), k in todo:
                srv.send(in_dim("execute if biome %d %d %d %s" % (x, y, z, cands[k])))
            nxt = []
            for (x, y, z, cands), k in todo:
                if srv.wait_for(PASS_RE, 120).group(1) == "passed":
                    out.append((x, y, z, cands[k]))
                elif k + 1 < len(cands):
                    nxt.append(((x, y, z, cands), k + 1))
                else:
                    raise RuntimeError("no candidate biome passes at %d %d %d" % (x, y, z))
            todo = nxt
        for cx, cz in need:
            srv.send(in_dim("forceload remove %d %d" % (cx * 16, cz * 16)))
    return sorted(out)


def run_world(mc, server_dir, cmd, seed, areas, level_type, port, logf, pack=None):
    level = "wg_%s_%d_%s" % (mc.replace(".", "_"), seed & 0xFFFFFFFFFFFFFFFF,
                             pack.name.replace(".", "_") if pack else level_type)
    remove_world(server_dir, level)
    write_properties(server_dir, seed, level, port, level_type_property(mc, level_type))
    if pack:
        pack.install(server_dir, level)
    # a start normally takes well under a minute; 1.18.2 sometimes hangs in it
    with Started(server_dir, cmd, log=logf, start_timeout=300, pack=pack) as srv:
        check_startup(srv, logf)
        frozen = can_freeze(mc)
        if frozen:
            # no block, fluid or random tick may touch the generated chunks
            srv.command("tick freeze", re.compile(r"frozen"), 120)
        else:
            # The world cannot be frozen: switch off what can be switched off ...
            for rule, value in (("randomTickSpeed", "0"), ("doWeatherCycle", "false"),
                                ("doMobSpawning", "false"), ("mobGriefing", "false"),
                                ("doFireTick", "false")):
                srv.command("gamerule %s %s" % (rule, value),
                            re.compile(r"%s is now set to" % rule), 120)
            # ... and move the world spawn away, so that the always-loaded spawn
            # chunks do not keep ticking inside an area for the whole run.
            srv.command("setworldspawn %d %d %d" % far_from(areas),
                        re.compile(r"Set the world spawn point to"), 120)
        # Data pack worlds only (the worlds of the two built-in world types keep
        # the behaviour their files were made with): hold every block of chunks
        # until vanilla has post-processed it.
        generate(srv, areas, until_ticking=bool(pack) and has_if_loaded(mc))
        chunks = None
        for _ in range(60):
            srv.save_flush()
            world = mcworld.World(dim_region_dir(server_dir, level))
            chunks, missing = read_chunks(world, areas)
            if chunks is not None:
                break
            time.sleep(2)
        if chunks is None:
            raise RuntimeError("chunk %d,%d not saved as a full chunk (status %s)" % missing)
        if pack:
            noise = pack.check_world(server_dir, level)
        else:
            noise = pr.check_level_type(server_dir, level, level_type)
        noise = dimension_noise(server_dir, level, pack, noise)
        recs, st, tops = extract(chunks, areas, bool(pack))
        if offline_errors(st):
            raise RuntimeError("heightmaps disagree with the stored blocks: %s"
                               % json.dumps(offline_errors(st)))
        live = live_checks(srv, mc, seed, recs, tops, chunks)
        zooms = zoom_reference(srv, seed, chunks, ZOOM) if ZOOM and has_if_biome(mc) else []
    # The server has stopped: the data is what is on disk now.
    world = mcworld.World(dim_region_dir(server_dir, level))
    chunks2, missing = read_chunks(world, areas)
    if chunks2 is None:
        raise RuntimeError("chunk %d,%d is not a full chunk after the server stop (status %s)" % missing)
    recs2, st2, tops2 = extract(chunks2, areas, bool(pack))
    drift = 0
    changed = []
    for name in recs:
        if recs[name][1] != recs2[name][1]:
            raise RuntimeError("biomes changed between the save and the server stop")
        changed += [(a, b) for a, b in zip(recs[name][0], recs2[name][0]) if a != b]
    drift = len(changed)
    if frozen:
        if drift:
            for a, b in changed[:8]:
                log("  column %d %d: world_surface %d -> %d (%s -> %s), ocean_floor %d -> %d (%s -> %s)"
                    % (a[0], a[1], a[2], b[2], tops[a[:2]][0], tops2[a[:2]][0],
                       a[3], b[3], tops[a[:2]][1], tops2[a[:2]][1]))
            raise RuntimeError("world changed between the save and the server stop (%d columns)" % drift)
    else:
        # Loaded chunks kept ticking (the live checks load some again): a few
        # columns differ from the state the live checks saw. The final state is
        # the one written, so it has to pass the offline checks itself.
        if drift > MAX_DRIFT * st2["h"]:
            raise RuntimeError("%d of %d columns changed between the save and the server stop"
                               % (drift, st2["h"]))
        if offline_errors(st2):
            raise RuntimeError("final heightmaps disagree with the stored blocks: %s"
                               % json.dumps(offline_errors(st2)))
    st2["live_h"], st2["live_b"], st2["live_b_mixed"] = live
    st2["drift_h"] = drift
    st2["zoom"] = len(zooms)
    remove_world(server_dir, level)
    return recs2, st2, noise, frozen, zooms


# ---------------------------------------------------------- structure starts
#
# With --structures the tool records where vanilla started structures instead
# of heights and biomes. A structure start is decided and stored when a chunk
# reaches the status structure_starts, which vanilla also does for the ring of
# chunks around every chunk it generates in full (and saves them as proto
# chunks). Every saved chunk therefore says for itself whether a structure
# starts in it, so the tool force-loads single chunks on a coarse grid and
# reads every chunk of the region files. See README.md ("Structure starts").

STRUCT_WORLDS = os.path.join(HERE, "structures.txt")


class Grid:
    """Single chunks on a grid: nx x nz chunks, step chunks apart, from (cx0, cz0)."""

    def __init__(self, name, cx0, cz0, nx, nz, step):
        self.name, self.cx0, self.cz0, self.nx, self.nz, self.step = name, cx0, cz0, nx, nz, step

    def chunks(self):
        return [(self.cx0 + i * self.step, self.cz0 + j * self.step)
                for i in range(self.nx) for j in range(self.nz)]


def parse_struct_worlds(path):
    """Lines: '<seed> <name>:<chunk_x0>,<chunk_z0>,<count_x>,<count_z>,<step> ...'."""
    out = []
    with open(path) as f:
        for line in f:
            line = line.split("#", 1)[0].strip()
            if not line:
                continue
            p = line.split()
            grids = []
            for spec in p[1:]:
                name, nums = spec.split(":")
                grids.append(Grid(name, *[int(v) for v in nums.split(",")]))
            out.append((int(p[0]), grids))
    return out


def generate_chunks(srv, chunks, batch=8):
    """Generate single chunks to full, a few at a time, and release them again.

    Every forced chunk leaves some 700 chunks of lower status around it; the
    saves in between let the server write and drop them (a 4 GB heap ran out
    without them).
    """
    for i in range(0, len(chunks), batch):
        part = chunks[i:i + batch]
        for cx, cz in part:
            m = srv.command(in_dim("forceload add %d %d" % (cx * 16, cz * 16)), FORCE_RE, 300)
            if m.group(1) == "Too many chunks":
                raise SystemExit("forceload refused at chunk %d,%d" % (cx, cz))
        probe_loaded(srv, part)
        for cx, cz in part:
            srv.command(in_dim("forceload remove %d %d" % (cx * 16, cz * 16)), UNFORCE_RE, 300)
        srv.save_flush()


def _ints(v):
    return [int(x) for x in v]


def start_record(key, st, cx, cz):
    """One structure start: (structure, cx, cz, first piece, its box, extras)."""
    sid = st.get("id")
    if sid != key or (st.get("ChunkX"), st.get("ChunkZ")) != (cx, cz):
        raise RuntimeError("chunk %d,%d: start %r stored as %r at %s,%s"
                           % (cx, cz, key, sid, st.get("ChunkX"), st.get("ChunkZ")))
    ch = st.get("Children") or []
    if not ch:
        raise RuntimeError("chunk %d,%d: start %s without pieces" % (cx, cz, key))
    c0 = ch[0]
    bb = _ints(c0["BB"])
    box = [min(_ints(c["BB"])[k] for c in ch) for k in range(3)] + \
          [max(_ints(c["BB"])[k] for c in ch) for k in range(3, 6)]
    ex = [("pieces", str(len(ch))), ("box", ",".join(str(v) for v in box))]
    if "pool_element" in c0:
        # jigsaw: the start piece; the start position is the centre of its box
        el = c0["pool_element"]
        loc = el.get("location")
        if loc is None and el.get("elements"):
            loc = el["elements"][0].get("location")
        ex += [("element", "%s:%s" % (el.get("element_type", "?"), loc)),
               ("rot", c0.get("rotation", "?")),
               ("gld", str(c0.get("ground_level_delta", 0))),
               ("pos", "%d,%d,%d" % (c0["PosX"], c0["PosY"], c0["PosZ"]))]
    if "Template" in c0:
        ex += [("template", c0["Template"]), ("tp", "%d,%d,%d" % (c0["TPX"], c0["TPY"], c0["TPZ"]))]
        rot = c0.get("Rot", c0.get("Rotation"))
        if rot:
            ex.append(("rot", rot))
    return (key, cx, cz, c0.get("id", "?"), tuple(bb), tuple(ex))


def read_starts(region):
    """All saved chunks of a region directory: covered chunks, starts, status counts."""
    covered, starts, status = set(), [], {}
    for path in sorted(glob.glob(os.path.join(region, "r.*.*.mca"))):
        rx, rz = (int(v) for v in os.path.basename(path).split(".")[1:3])
        reg = mcworld.Region(path)
        for i in range(1024):
            cx, cz = rx * 32 + (i & 31), rz * 32 + (i >> 5)
            ch = reg.chunk(cx, cz)
            if ch is None:
                continue
            s = mcworld.chunk_status(ch)
            status[s] = status.get(s, 0) + 1
            if s in (None, "minecraft:empty", "empty"):
                continue
            if (ch["xPos"], ch["zPos"]) != (cx, cz):
                raise RuntimeError("chunk %d,%d stored as %s,%s" % (cx, cz, ch["xPos"], ch["zPos"]))
            covered.add((cx, cz))
            for key, st in sorted(mcworld.structure_starts(ch).items()):
                starts.append(start_record(key, st, cx, cz))
    starts.sort(key=lambda r: (r[0], r[1], r[2]))
    return covered, starts, status


def run_structures_world(mc, server_dir, cmd, seed, grids, level_type, port, logf, pack=None):
    level = "st_%s_%d_%s" % (mc.replace(".", "_"), seed & 0xFFFFFFFFFFFFFFFF,
                             pack.name.replace(".", "_") if pack else level_type)
    remove_world(server_dir, level)
    write_properties(server_dir, seed, level, port, level_type_property(mc, level_type))
    if pack:
        pack.install(server_dir, level)
    forced = [c for g in grids for c in g.chunks()]
    with Started(server_dir, cmd, log=logf, start_timeout=300, pack=pack) as srv:
        check_startup(srv, logf)
        frozen = can_freeze(mc)
        if frozen:
            srv.command("tick freeze", re.compile(r"frozen"), 120)
        t0 = time.time()
        generate_chunks(srv, forced)
        log("  %d grid chunks generated in %.0f s" % (len(forced), time.time() - t0))
        srv.save_flush()
        if pack:
            noise = pack.check_world(server_dir, level)
        else:
            noise = pr.check_level_type(server_dir, level, level_type)
        noise = dimension_noise(server_dir, level, pack, noise)
        covered, starts, status = read_starts(dim_region_dir(server_dir, level))
    # The server has stopped: everything it held is on disk now, and that is
    # what is written. Which structure starts where never changes once it is
    # stored, so the second read must contain the first. (The pieces of some
    # structures, shipwrecks and ocean ruins, are only moved to their final
    # height when the chunk is decorated, so their boxes may differ.)
    covered2, starts2, status2 = read_starts(dim_region_dir(server_dir, level))
    if not covered <= covered2 or not {s[:3] for s in starts} <= {s[:3] for s in starts2}:
        raise RuntimeError("starts changed between the save and the server stop")
    world = mcworld.World(dim_region_dir(server_dir, level))
    for cx, cz in forced:
        if mcworld.chunk_status(world.chunk(cx, cz)) not in ("minecraft:full", "full"):
            raise RuntimeError("grid chunk %d,%d is not a full chunk" % (cx, cz))
    remove_world(server_dir, level)
    return covered2, starts2, status2, noise, frozen


def coverage_rows(covered):
    """Runs of covered chunks per chunk row: (cz, cx0, cx1)."""
    rows = []
    for cz in sorted({c[1] for c in covered}):
        xs = sorted(c[0] for c in covered if c[1] == cz)
        a = b = xs[0]
        for x in xs[1:]:
            if x == b + 1:
                b = x
                continue
            rows.append((cz, a, b))
            a = b = x
        rows.append((cz, a, b))
    return rows


def struct_out_name(prefix, mc, seed):
    return "structures_%s_%s_%d.txt" % (prefix, mc, seed)


def write_structures_file(path, tmp, mc, jar_sha1, level_type, noise, seed, frozen, grids,
                          covered, starts, pack=None):
    with open(tmp, "w") as f:
        f.write("# Seed Atlas structure start reference data, vanilla Minecraft %s dedicated server, sha1 %s\n"
                % (mc, jar_sha1))
        f.write("# generated by tools/worldgen-reference/worldgen_reference.py --structures,"
                " format: tools/worldgen-reference/README.md\n")
        f.write("# mc %s\n# level_type %s\n" % (mc, level_type))
        if pack:
            f.write("# datapack %s sha1 %s files %d\n" % (pack.name, pack.sha1, pack.files))
        f.write("# noise_settings %s\n# seed %d\n" % (noise, seed))
        if DIMENSION:
            f.write("# dimension %s\n" % DIMENSION)
        f.write("# ticks %s\n" % ("frozen" if frozen else "running"))
        for g in grids:
            f.write("# grid %s %d %d %d %d %d\n" % (g.name, g.cx0, g.cz0, g.nx, g.nz, g.step))
        f.write("# chunks %d starts %d\n" % (len(covered), len(starts)))
        f.write("# C <chunk_z> <chunk_x0> <chunk_x1>\n")
        f.write("# S <structure> <chunk_x> <chunk_z> <piece> <x0> <y0> <z0> <x1> <y1> <z1> [<key>=<value> ...]\n")
        for r in coverage_rows(covered):
            f.write("C %d %d %d\n" % r)
        for sid, cx, cz, piece, bb, ex in starts:
            f.write("S %s %d %d %s %s%s\n" % (sid, cx, cz, piece, " ".join(str(v) for v in bb),
                                            "".join(" %s=%s" % kv for kv in ex)))
    try:
        os.replace(tmp, path)
    except OSError:
        shutil.copyfile(tmp, path + ".part")
        os.replace(path + ".part", path)
        os.remove(tmp)


def main_structures(args, jsha, sdir, cmd, pack, logf, prefix):
    for seed, grids in parse_struct_worlds(args.worlds or STRUCT_WORLDS):
        if args.seed and seed not in args.seed:
            continue
        name = struct_out_name(prefix, args.mc, seed)
        path = os.path.join(args.out, name)
        if os.path.exists(path) and not args.force:
            continue
        log("mc %s %s seed %d: structures, %d grid chunks"
            % (args.mc, prefix, seed, sum(len(g.chunks()) for g in grids)))
        for attempt in range(3):
            try:
                covered, starts, status, noise, frozen = run_structures_world(
                    args.mc, sdir, cmd, seed, grids, args.level_type, args.port, logf, pack)
                break
            except (RuntimeError, TimeoutError) as e:
                log("  attempt %d failed: %s" % (attempt + 1, e))
                if attempt == 2:
                    raise
        write_structures_file(path, os.path.join(args.work, name + ".tmp"), args.mc, jsha,
                              args.level_type, noise, seed, frozen, grids, covered, starts, pack)
        count = {}
        for s in starts:
            count[s[0]] = count.get(s[0], 0) + 1
        log("  wrote %s: %d chunks, %d starts %s; chunk status %s"
            % (name, len(covered), len(starts), json.dumps(count, sort_keys=True),
               json.dumps(status, sort_keys=True)))


# -------------------------------------------------------------------- output

def out_name(level_type, mc, seed):
    return "%s_%s_%d.txt" % (level_type, mc, seed)


def write_file(path, tmp, mc, jar_sha1, level_type, noise, seed, frozen, areas, recs, pack=None, zooms=()):
    with open(tmp, "w") as f:
        f.write("# Seed Atlas worldgen reference data, vanilla Minecraft %s dedicated server, sha1 %s\n"
                % (mc, jar_sha1))
        f.write("# generated by tools/worldgen-reference/worldgen_reference.py,"
                " format: tools/worldgen-reference/README.md\n")
        f.write("# mc %s\n# level_type %s\n" % (mc, level_type))
        if pack:
            f.write("# datapack %s sha1 %s files %d\n" % (pack.name, pack.sha1, pack.files))
        if TERRAIN_ONLY:
            f.write("# terrain_only features, carvers and structures removed\n")
        f.write("# noise_settings %s\n# seed %d\n" % (noise, seed))
        if DIMENSION:
            f.write("# dimension %s\n" % DIMENSION)
        f.write("# min_y %d height %d sea_level %d\n" % (MIN_Y, HEIGHT, SEA_LEVEL))
        f.write("# ticks %s\n" % ("frozen" if frozen else "running"))
        for a in areas:
            f.write("# area %s %d %d %d %d\n" % ((a.name,) + a.box()))
        f.write("# H <x> <z> <world_surface> <ocean_floor>\n# B <x> <y> <z> <biome>\n")
        if FLOOR_BELOW is not None:
            f.write("# F <x> <z> <highest block at or below y %d that is not air or a fluid>\n"
                    % FLOOR_BELOW)
        for a in areas:
            hs, bs = recs[a.name]
            f.write("# area %s\n" % a.name)
            f.writelines("H %d %d %d %d\n" % r for r in hs)
            if FLOOR_BELOW is not None:
                f.writelines("F %d %d %d\n" % r for r in FLOORS[a.name])
            f.writelines("B %d %d %d %s\n" % r for r in bs)
        if zooms:
            f.write("# zoom\n# Z <x> <y> <z> <biome of the block (execute if biome, the game's 1:1 zoom)>\n")
            f.writelines("Z %d %d %d %s\n" % r for r in zooms)
    # move into place in one step so that nobody reads half a file
    try:
        os.replace(tmp, path)
    except OSError:  # other file system
        shutil.copyfile(tmp, path + ".part")
        os.replace(path + ".part", path)
        os.remove(tmp)


def percentile(sorted_vals, p):
    if not sorted_vals:
        return None
    return sorted_vals[min(len(sorted_vals) - 1, int(p / 100.0 * len(sorted_vals)))]


def summarize(recs):
    """Numbers for the log: land heights and the ocean sanity check."""
    hs = [r for h, _ in recs.values() for r in h]
    bs = [r for _, b in recs.values() for r in b]
    land = sorted(r[2] for r in hs if r[3] >= SEA_LEVEL)
    landf = sorted(r[3] for r in hs if r[3] >= SEA_LEVEL)
    hmap = {(r[0], r[1]): r for r in hs}
    ocean = [hmap[(x, z)] for x, y, z, b in bs if y == 64 and b.endswith("ocean")]
    return {
        "columns": len(hs), "land": len(land),
        "land_ws_p50_p90_p99_max": [percentile(land, 50), percentile(land, 90), percentile(land, 99),
                                    land[-1] if land else None],
        "land_of_p50_p90_p99_max": [percentile(landf, 50), percentile(landf, 90), percentile(landf, 99),
                                    landf[-1] if landf else None],
        "ocean_biome_columns": len(ocean),
        "ocean_biome_ws62": sum(1 for r in ocean if r[2] == SEA_LEVEL - 1),
        "ws62_columns": sum(1 for r in hs if r[2] == SEA_LEVEL - 1),
    }


def main():
    # turn SIGTERM into SystemExit so the server context manager stops the server
    signal.signal(signal.SIGTERM, lambda *a: sys.exit(143))
    ap = argparse.ArgumentParser()
    ap.add_argument("--mc", required=True)
    ap.add_argument("--level-type", default="normal", choices=("normal", "amplified"))
    ap.add_argument("--worlds", help="worlds file (default worlds.txt, with --structures structures.txt)")
    ap.add_argument("--structures", action="store_true",
                    help="record structure starts (structures_<...>.txt) instead of heights and biomes")
    ap.add_argument("--work", required=True, help="scratch dir for jars, server and worlds")
    ap.add_argument("--out", default=os.path.join(HERE, "data"))
    ap.add_argument("--jar", help="official server jar (verified by sha1)")
    ap.add_argument("--java", default="java")
    ap.add_argument("--heap", default="2G", help="Java heap of the server (-Xmx)")
    ap.add_argument("--port", type=int, default=25951)
    ap.add_argument("--accept-eula", action="store_true",
                    help="you accept Mojang's EULA (https://aka.ms/MinecraftEULA) for the temporary server;"
                    " required (or MINECRAFT_ACCEPT_EULA=1)")
    ap.add_argument("--bg-threads", type=int, help="limit worldgen worker threads (1.18.2 races)")
    ap.add_argument("--seed", type=int, action="append", help="only these seeds of the worlds file")
    ap.add_argument("--force", action="store_true", help="regenerate files that already exist")
    ap.add_argument("--datapack", help="data pack (folder or zip) put into every world before it is created")
    ap.add_argument("--datapack-name", help="name of the pack in the world and in the file names"
                                            " (default: name of the folder or zip)")
    ap.add_argument("--dimension",
                    help="record another dimension than the overworld: nether, end (files nether_/end_...)"
                    " or the id of a data pack's dimension (files <pack>-<namespace>_<path>_...)")
    ap.add_argument("--terrain-only", action="store_true",
                    help="data packs: generate the worlds without features, carvers and structures (a second pack"
                    " made at run time overrides every biome and structure set), files <pack>-terrain_...")
    ap.add_argument("--allow-warnings", action="store_true",
                    help="data packs: go on when the server logs warnings or errors while it loads the"
                    " pack (they stay in the server log); without it such a pack ends the run")
    ap.add_argument("--area", action="append", help="only these areas of the worlds file (by name)")
    ap.add_argument("--zoom", type=int, default=0, metavar="N",
                    help="also N Z lines: the biome vanilla reports for single blocks where the 1:1 zoom"
                    " decides between cells (1.19.3 and later)")
    ap.add_argument("--h-step", type=int, choices=(1, 2, 4), default=4,
                    help="H (and F) columns every N blocks (default 4, the files in data/)")
    args = ap.parse_args()
    # a selection that matches nothing is an error, not a file without data
    if args.structures:
        if args.area:
            raise SystemExit("--area is not used with --structures")
        worlds = None
        known = {seed for seed, _ in parse_struct_worlds(args.worlds or STRUCT_WORLDS)}
    else:
        worlds = parse_worlds(args.worlds or os.path.join(HERE, "worlds.txt"))
        known = {seed for seed, _ in worlds}
    if args.seed:
        missing = sorted(set(args.seed) - known)
        if missing:
            raise SystemExit("--seed: not in the worlds file: %s" % ", ".join(str(v) for v in missing))
    if args.area:
        names = {a.name for seed, areas in worlds if not args.seed or seed in args.seed for a in areas}
        missing = sorted(set(args.area) - names)
        if missing:
            raise SystemExit("--area: no such area (of the chosen seeds): %s" % ", ".join(missing))
    require_eula(args.accept_eula)
    global DIMENSION, MIN_Y, HEIGHT, SEA_LEVEL, BIOME_Y, H_STEP, FLOOR_BELOW, ALLOW_WARNINGS
    H_STEP = args.h_step
    ALLOW_WARNINGS = args.allow_warnings
    if args.dimension in DIMENSIONS:
        DIMENSION, _, MIN_Y, HEIGHT, SEA_LEVEL, BIOME_Y = DIMENSIONS[args.dimension]
        if DIMENSION == "minecraft:the_nether":
            FLOOR_BELOW = NETHER_FLOOR_BELOW
    elif args.dimension:
        if not re.match(r"^[a-z0-9_.-]+:[a-z0-9_./-]+$", args.dimension):
            raise SystemExit("--dimension: nether, end or a dimension id such as somepack:somewhere")
        if not args.datapack and args.dimension not in PRESET_DIMENSIONS:
            raise SystemExit("--dimension %s: only a data pack defines other dimensions" % args.dimension)
        DIMENSION = args.dimension
    if args.datapack and args.level_type != "normal":
        raise SystemExit("--datapack is only supported with --level-type normal")

    work = os.path.abspath(args.work)
    os.makedirs(work, exist_ok=True)
    os.makedirs(args.out, exist_ok=True)
    jar = pr.obtain_jar(args.mc, work, args.jar)
    jsha = pr.sha1_of(jar)
    sdir, cmd, _ = pr.prepare_server_dir(args.mc, work, jar, args.java, args.heap, "wg-server-%s" % args.mc)
    if args.bg_threads:
        cmd.insert(1, "-Dmax.bg.threads=%d" % args.bg_threads)
    pack = Pack(args.datapack, work, args.datapack_name) if args.datapack else None
    if pack:
        log("pack %s: %d files, zip sha1 %s, overworld settings %s, %s biome entries"
            % (pack.name, pack.files, pack.sha1, pack.settings, pack.entries))
        # The dimension's heights come from the dimension type and noise
        # settings its generator names, which the pack may replace.
        pack.use_format(data_format(jar))
        dim = DIMENSION or "minecraft:overworld"
        MIN_Y, HEIGHT, logical, ceiling, SEA_LEVEL = dimension_geometry(dim, pack)
        BIOME_Y = biome_levels(MIN_Y, HEIGHT)
        FLOOR_BELOW = MIN_Y + logical * NETHER_FLOOR_BELOW // 128 if ceiling else None
        log("dimension %s: min_y %d height %d sea_level %d%s, B lines at y %s"
            % (dim, MIN_Y, HEIGHT, SEA_LEVEL, ", F lines below y %d" % FLOOR_BELOW if FLOOR_BELOW is not None
               else "", " ".join(str(y) for y in BIOME_Y)))
    if args.zoom:
        global ZOOM
        ZOOM = args.zoom
    if args.terrain_only:
        global TERRAIN_ONLY
        if not pack:
            raise SystemExit("--terrain-only needs --datapack")
        if version_tuple(args.mc) < [1, 19]:
            raise SystemExit("--terrain-only: structure sets have no frequency before 1.19")
        TERRAIN_ONLY = os.path.join(work, "%s-%s.zip" % (TERRAIN_ONLY_NAME, pack.name))
        nb, ns = make_terrain_only(pack, jar, data_format(jar), TERRAIN_ONLY)
        log("terrain only: %d biomes without features and carvers, %d structure sets with frequency 0"
            % (nb, ns))
    prefix = pack.name if pack else args.level_type
    if args.terrain_only:
        prefix += "-terrain"
    if args.dimension:
        if args.level_type != "normal":
            raise SystemExit("--dimension is only supported with --level-type normal")
        prefix = (prefix + "-" if pack else "") + \
            (args.dimension if args.dimension in DIMENSIONS else args.dimension.replace(":", "_").replace("/", "_"))
    logf = open(os.path.join(work, "wg-server-%s-%s.log" % (args.mc, prefix)), "a")
    if args.structures:
        main_structures(args, jsha, sdir, cmd, pack, logf, prefix)
        return
    for seed, areas in worlds:
        if args.seed and seed not in args.seed:
            continue
        if args.area:
            areas = [a for a in areas if a.name in args.area]
            if not areas:
                # the areas are of other seeds: no file with a header only
                continue
        name = out_name(prefix, args.mc, seed)
        path = os.path.join(args.out, name)
        if os.path.exists(path) and not args.force:
            continue
        log("mc %s %s seed %d: %d chunks in %d areas"
            % (args.mc, prefix, seed, sum(len(a.chunks()) for a in areas), len(areas)))
        for attempt in range(3):
            try:
                recs, st, noise, frozen, zooms = run_world(args.mc, sdir, cmd, seed, areas, args.level_type,
                                                           args.port, logf, pack)
                break
            except (RuntimeError, TimeoutError) as e:
                # e.g. 1.18.2's sporadic worldgen worker crash; start over with a fresh world
                log("  attempt %d failed: %s" % (attempt + 1, e))
                if attempt == 2:
                    raise
        write_file(path, os.path.join(work, name + ".tmp"), args.mc, jsha, args.level_type, noise, seed,
                   frozen, areas, recs, pack, zooms)
        st["summary"] = summarize(recs)
        with open(os.path.join(work, "stats-" + name[:-4] + ".json"), "w") as f:
            json.dump(st, f, indent=1, sort_keys=True)
        log("  wrote %s: %d H, %d B lines; live checks %d columns, %d biome positions (%d mixed);"
            " %d columns changed after the first save; %s"
            % (name, st["h"], st["b"], st["live_h"], st["live_b"], st["live_b_mixed"], st["drift_h"],
               json.dumps(st["summary"])))


if __name__ == "__main__":
    main()
